 * @param {string} input - the raw election text read from standard input.
 * @returns {{candidates: string[], ballots: {count: bigint, names: string[]}[]}}
 * @throws {ElectionError} when the input does not follow the grammar.
 */
export function parseElection(input) {
  const rawLines = input.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') {
    rawLines.pop()
  }

  let candidatesDeclared = false
  let candidates = []
  let candidateSet = new Set()
  const ballots = []

  for (let i = 0; i < rawLines.length; i++) {
    const lineNo = i + 1
    const trimmed = rawLines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'candidates') {
      if (candidatesDeclared) {
        throw new ElectionError('candidates must be declared once, before any ballot', lineNo)
      }
      if (tokens.length < 2) {
        throw new ElectionError('expected candidates <name>...', lineNo)
      }
      const names = tokens.slice(1)
      const seen = new Set()
      for (const name of names) {
        if (!NAME_RE.test(name)) {
          throw new ElectionError(`invalid candidate name ${name}`, lineNo)
        }
        if (seen.has(name)) {
          throw new ElectionError(`candidate ${name} is declared twice`, lineNo)
        }
        seen.add(name)
      }
      candidates = names
      candidateSet = seen
      candidatesDeclared = true
    } else if (directive === 'ballot') {
      if (!candidatesDeclared) {
        throw new ElectionError('candidates must be declared once, before any ballot', lineNo)
      }
      if (tokens.length < 3) {
        throw new ElectionError('expected ballot <count> <candidate>...', lineNo)
      }
      const countToken = tokens[1]
      if (!COUNT_RE.test(countToken)) {
        throw new ElectionError('count must be a positive integer', lineNo)
      }
      const names = tokens.slice(2)
      const seen = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          throw new ElectionError(`unknown candidate ${name}`, lineNo)
        }
        if (seen.has(name)) {
          throw new ElectionError(`candidate ${name} is repeated`, lineNo)
        }
        seen.add(name)
      }
      ballots.push({ count: BigInt(countToken), names })
    } else {
      throw new ElectionError(`unknown directive ${directive}`, lineNo)
    }
  }

  if (!candidatesDeclared) {
    throw new ElectionError('no candidates')
  }

  return { candidates, ballots }
}
