{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T000002Z/cell-6g0mko/src/election.js","content":"/**
 * Run an instant-runoff count over a parsed election.
 *
 * @param {{candidates: string[], ballots: {count: bigint, names: string[]}[]}} election
 * @returns {{rounds: {counts: Map<string, bigint>, exhausted: bigint, eliminated: string|null}[], winner: string|null}}
 */
export function runElection(election) {
  const { candidates, ballots } = election
  const continuing = new Set(candidates)
  const history = []
  const rounds = []
  let winner = null

  for (;;) {
    const counts = new Map()
    for (const name of continuing) counts.set(name, 0n)
    let exhausted = 0n

    for (const ballot of ballots) {
      const target = ballot.names.find((name) => continuing.has(name))
      if (target === undefined) {
        exhausted += ballot.count
      } else {
        counts.set(target, counts.get(target) + ballot.count)
      }
    }

    history.push(counts)

    let activeTotal = 0n
    for (const v of counts.values()) activeTotal += v

    if (activeTotal === 0n) {
      rounds.push({ counts, exhausted, eliminated: null })
      break
    }

    const roundWinner = [...counts].find(([, v]) => v * 2n > activeTotal)
    if (roundWinner !== undefined) {
      winner = roundWinner[0]
      rounds.push({ counts, exhausted, eliminated: null })
      break
    }

    const eliminated = pickElimination(continuing, counts, history)
    rounds.push({ counts, exhausted, eliminated })
    continuing.delete(eliminated)
  }

  return { rounds, winner }
}

/**
 * Choose the candidate to eliminate this round: the one with the fewest
 * votes, breaking ties by comparing vote counts round by round from the
 * first round onwards and, failing that, by name.
 *
 * @param {Set<string>} continuing - candidates still in the running.
 * @param {Map<string, bigint>} counts - this round's vote counts.
 * @param {Map<string, bigint>[]} history - vote counts for every round so far, this one included.
 * @returns {string}
 */
function pickElimination(continuing, counts, history) {
  let min = null
  for (const name of continuing) {
    const v = counts.get(name)
    if (min === null || v < min) min = v
  }
  let group = [...continuing].filter((name) => counts.get(name) === min)

  for (const roundCounts of history) {
    if (group.length === 1) break
    const values = group.map((name) => roundCounts.get(name))
    const allEqual = values.every((v) => v === values[0])
    if (!allEqual) {
      let least = values[0]
      for (const v of values) if (v < least) least = v
      group = group.filter((_, idx) => values[idx] === least)
    }
  }

  if (group.length === 1) return group[0]
  group.sort()
  return group[group.length - 1]
}
"}

